        {
          "id": "prop-emg-fx-discrete-gauss-preservation",
          "kind": "proposition",
          "domain": "mathematics",
          "title": "Exact discrete constraints and semidiscrete and staggered energy",
          "reference": "research/plan-einstein-maxwell-models-frontier-expansion-track.md#emg-fx10-compatible-discrete-maxwell-constraints-and-finite-algorithms",
          "design_state": "Step 1 authored draft; readiness recorded separately.",
          "dependency_level": 2,
          "deps": [
