        {
          "id": "lem-gr-fx04-conformal-scalar-curvature",
          "kind": "lemma",
          "domain": "mathematics",
          "title": "Scalar curvature of a conformally Euclidean three-metric",
          "reference": "items/lem-gr-fx04-conformal-scalar-curvature.md",
          "design_state": "Step 1 authoring complete draft; readiness recorded separately.",
          "dependency_level": 0,
