        {
          "id": "prop-gr-fx-conformal-adm-value",
          "kind": "proposition",
          "domain": "mathematics",
          "title": "ADM energy of a conformally flat end",
          "reference": "items/prop-gr-fx-conformal-adm-value.md",
          "design_state": "Step 1 authoring complete draft; readiness recorded separately.",
          "dependency_level": 1,
          "deps": [
            "def-gr-fx-adm-end"
          ],
          "dependency_roles": {
            "def-gr-fx-adm-end": "mathematical-premise"
          },
          "physical_scope": "A fixed-chart calculation for a conformally flat end; no constraint equation, positivity result, or empirical claim is inferred.",
          "inventory_expansion_required": false,
          "statement": "On a fixed-chart end $E=\\{x\\in\\mathbb R^3:r=|x|>R_0\\}$ with the ADM convention stated below, let $u\\in C^\\infty(E,(0,\\infty))$ satisfy $u=1+m/(2r)+\\rho$, where $m\\in\\mathbb R$ has units of metres and $\\rho=O_2(r^{-2})$. Set $h=u^4\\delta$ and choose any $C^1$ symmetric tensor $K=O_1(r^{-2})$. Then the ADM limit exists in the specified chart and\n$$E_{\\mathrm{ADM}}(h;x)=\\frac{c^4m}{G_N}.$$",
