          "title": "Compact interior changes leave a fixed ADM integral unchanged",
          "reference": "items/prop-gr-fx-compact-change-adm.md",
          "design_state": "Step 1 authoring complete draft; readiness recorded separately.",
          "dependency_level": 1,
          "deps": [
            "def-gr-fx-adm-end"
