          "id": "def-gr-fx-bianchi-i-data",
          "kind": "definition",
          "domain": "mathematics",
          "title": "Diagonal Bianchi I model",
          "reference": "prose-scaffold.md (FX10)",
          "design_state": "completed-local-definition",
          "dependency_level": 0,
          "deps": [
