          "id": "lem-nrqmx-bernoulli-hoeffding",
          "kind": "lemma",
          "domain": "mathematics",
          "title": "Two-sided Hoeffding bound for Bernoulli frequencies",
          "reference": "items/lem-nrqmx-bernoulli-hoeffding.md",
