        {
          "id": "alg-qsmx-schmidt-mps-truncation",
          "kind": "algorithm",
          "domain": "mathematics",
          "title": "Sequential Schmidt truncation",
          "reference": "research/frontier-expansion-2026-10-19/quantum-statistical-mechanics/prose-scaffold.md#alg-qsmx-schmidt-mps-truncation",
          "design_state": "draft-research",
          "dependency_level": 1,
          "deps": [
