          "title": "Toric-code edge spins on closed-surface cellulations",
          "reference": "research/frontier-expansion-2026-10-19/quantum-statistical-mechanics/prose-scaffold.md#def-qsmx-toric-cellular-hamiltonian",
          "design_state": "draft-research",
