          "kind": "definition",
          "domain": "mathematics",
          "title": "Finite energy-resolved GKSL thermal model",
          "reference": "research/frontier-expansion-2026-10-19/quantum-statistical-mechanics/prose-scaffold.md#def-qsmx-secular-thermal-generator",
