          "id": "thm-qsmx-spohn-finite-inequality",
          "kind": "theorem",
          "domain": "mathematics",
          "title": "Stationary finite quantum semigroups decrease relative entropy",
          "reference": "research/frontier-expansion-2026-10-19/quantum-statistical-mechanics/prose-scaffold.md#thm-qsmx-spohn-finite-inequality",
