        {
          "id": "lem-tgrx-compensator-implies-exact",
          "kind": "lemma",
          "domain": "mathematics",
          "title": "A global potential compensator makes the contracted field exact",
          "reference": "research/physics-non-fluid-129-2026-10-21-r2-batch-115.notes.md#compensator-lemma",
          "design_state": "local-prerequisite",
          "dependency_level": 0,
          "deps": [
