          "title": "Rotation and charged equilibrium obstruction",
          "reference": "research/frontier-expansion-2026-10-19/thermodynamics-and-general-relativity/prose-scaffold.md#prop-tgrx-equilibrium-obstructions",
          "design_state": "draft-research",
          "dependency_level": 2,
          "deps": [
            "def-tgrx-thermal-vorticity",
            "def-tgrx-period-of-one-form",
            "lem-tgrx-exact-one-form-zero-period",
            "def-tgr-charged-liouville-data",
