{
      "id": "tgrx-noether-entropy",
      "title": "Covariant stationary Noether charge and Wald entropy",
      "kind": "A",
      "category": "thermodynamics-and-general-relativity",
      "library": "physics",
      "companion": "tgrx-noether-entropy-examples",
