        },
        {
          "id": "pthm-tgrx-noether-charge-decomposition",
          "kind": "physics-theorem",
          "domain": "physics",
          "library": "physics",
          "title": "Noether charge decomposition for algebraic-curvature Lagrangians",
          "reference": "items/pthm-tgrx-noether-charge-decomposition.md#statement",
          "design_state": "Step 1 carrier authored for batch 117; local support item added only where needed to prove the planned stationary Noether-charge result.",
