          "id": "rem-tgrx-jt-completion-notunique",
          "kind": "remark",
          "title": "The JT disk density does not determine a unique nonperturbative completion",
          "domain": "physics",
          "library": "physics",
          "dependency_level": 1,
          "deps": [
