          "reference": "research/plan-thermodynamics-and-general-relativity-frontier-expansion-track.md#tgrx-research-boundaries",
          "design_state": "A conditional research question for an existing four-dimensional semiclassical Einstein-scalar collapse solution; asks for finite regulator-independent generalized-entropy differences and future monotonicity without assuming modular-energy/area balance.",
          "dependency_level": 6,
          "deps": [
            "post-tgrx-semiclassical-equation",
